import React from 'react'
import { Link } from 'react-router-dom'
import 'bootstrap/dist/css/bootstrap.min.css';
import Navbar from 'react-bootstrap/Navbar';
import Container from 'react-bootstrap/Container';
import Button from 'react-bootstrap/Button';

const Header = () => {
  return (
    <div>
    <Navbar expand="lg" className="bg-dark">
    <Container>
    <Navbar.Brand href='/' className='text-white'>Simple Login/Signup System</Navbar.Brand>
    <div>
        <Button variant="primary" className='me-4' as={Link} to="/login">Login</Button>
        <Button variant="outline-light" as={Link} to="/signup">Signup</Button>
    </div>
      </Container>
      </Navbar>
    </div>
  )
}

export default Header
